import{_ as t,o as a,c as o,a4 as l}from"./chunks/framework.9tZL7ZIQ.js";const n=JSON.parse('{"title":"能力圈","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-theme/能力圈.md","filePath":"05_quotes/by-theme/能力圈.md"}'),r={name:"05_quotes/by-theme/能力圈.md"};function u(i,e,q,s,c,h){return a(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="能力圈" tabindex="-1">能力圈 <a class="header-anchor" href="#能力圈" aria-label="Permalink to &quot;能力圈&quot;">​</a></h1><blockquote><p>&quot;知道你不知道什么，比你知道什么更重要。&quot;——巴菲特</p></blockquote><p>能力圈原则是巴菲特1996年伯克希尔股东手册中系统阐述的投资纪律。</p><hr><h2 id="经典语录" tabindex="-1">经典语录 <a class="header-anchor" href="#经典语录" aria-label="Permalink to &quot;经典语录&quot;">​</a></h2><blockquote><p>&quot;投资的全部秘诀归结为：在你能力圈内行事，在你非常了解的领域中寻找价值。&quot;</p></blockquote><blockquote><p>&quot;我们只在看得懂的机会上下注。不了解的东西再多也不是机会。我们不会因为别人在做什么就去做什么。&quot;</p></blockquote><blockquote><p>&quot;能力圈的大小不是问题，边界在哪里才是问题。你不需要对所有事情都了解，只需要在你的领域里做到极致。&quot;</p></blockquote><blockquote><p>&quot;科技股在我的能力圈之外。尽管很多人从中获利，但我看不懂，所以我不投资。这是我给自己的纪律。&quot;</p></blockquote><blockquote><p>&quot;我们选择可交易股权的方法，和我们整体收购企业时评估业务的方法几乎一模一样：我们希望这家企业是我们能理解的。&quot;</p></blockquote><hr><h2 id="出处年份" tabindex="-1">出处年份 <a class="header-anchor" href="#出处年份" aria-label="Permalink to &quot;出处年份&quot;">​</a></h2><h2 id="_1991年-·-1996年-·-1999年-·-2000年-·-2016年-·-2020年" tabindex="-1">1991年 · 1996年 · 1999年 · 2000年 · 2016年 · 2020年 <a class="header-anchor" href="#_1991年-·-1996年-·-1999年-·-2000年-·-2016年-·-2020年" aria-label="Permalink to &quot;1991年 · 1996年 · 1999年 · 2000年 · 2016年 · 2020年&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该主题在致股东信中的关键出处年份：</p><ul><li><a href="/01_letters/1991年/翻译">/01_letters/1991年/翻译</a></li><li><a href="/01_letters/1996年/翻译">/01_letters/1996年/翻译</a></li><li><a href="/01_letters/1999年/翻译">/01_letters/1999年/翻译</a></li></ul>',16)])])}const p=t(r,[["render",u]]);export{n as __pageData,p as default}